use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let intervals: Vec<(i64, i64)> = input
        .as_array()
        .unwrap()
        .iter()
        .map(|v| (v[0].as_i64().unwrap(), v[1].as_i64().unwrap()))
        .collect();

    let mut intervals = intervals;
    intervals.sort_by_key(|&(a, _)| a);

    let mut result = 0;
    let mut start = intervals[0].0;
    let mut end = intervals[0].1;

    for &interval in &intervals[1..] {
        if interval.0 <= end {
            end = std::cmp::max(end, interval.1);
        } else {
            result = std::cmp::max(result, end - start);
            start = interval.0;
            end = interval.1;
        }
    }

    result = std::cmp::max(result, end - start);
    Value::from(result)
}
